<?php
// public/appeal/index.php
// Appeal page for users whose comments have been hidden.
// URL: /appeal?token={signed_token}
// The token is generated by ModerationService::generateAppealToken()
// and embedded in the reply posted under the hidden comment on Facebook.

declare(strict_types=1);

require_once __DIR__ . '/../../vendor/autoload.php';

use Illuminate\Database\Capsule\Manager as DB;
use Dotenv\Dotenv;

// ── Bootstrap ─────────────────────────────────────────────────────────────
$dotenv = Dotenv::createImmutable(__DIR__ . '/../../');
$dotenv->safeLoad();

$capsule = new DB();
$capsule->addConnection([
    'driver'    => 'mysql',
    'host'      => $_ENV['DB_HOST']     ?? '127.0.0.1',
    'port'      => $_ENV['DB_PORT']     ?? '3306',
    'database'  => $_ENV['DB_DATABASE'] ?? 'moderation_hub',
    'username'  => $_ENV['DB_USERNAME'] ?? 'root',
    'password'  => $_ENV['DB_PASSWORD'] ?? '',
    'charset'   => 'utf8mb4',
    'collation' => 'utf8mb4_unicode_ci',
]);
$capsule->setAsGlobal();
$capsule->bootEloquent();

// ── Helpers ────────────────────────────────────────────────────────────────
function verifyToken(string $token): ?array
{
    try {
        $padded  = str_pad($token, strlen($token) + (4 - strlen($token) % 4) % 4, '=');
        $decoded = base64_decode($padded, strict: true);
        if ($decoded === false) return null;

        $parts = explode(':', $decoded, 4);
        if (count($parts) !== 4) return null;
        [$commentId, $socialUserId, $expires, $sig] = $parts;

        // No weak fallback: without a real secret, fail closed (tokens must be unforgeable).
        $secret = (string) ($_ENV['APP_SECRET'] ?? '');
        if ($secret === '') return null;
        $payload  = "{$commentId}:{$socialUserId}:{$expires}";
        $expected = hash_hmac('sha256', $payload, $secret);

        if (!hash_equals($expected, $sig))      return null;
        if ((int) $expires < time())            return null;

        return ['comment_id' => (int) $commentId, 'social_user_id' => (int) $socialUserId];
    } catch (\Throwable) {
        return null;
    }
}

function h(string $s): string
{
    return htmlspecialchars($s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
}

// ── Route logic ────────────────────────────────────────────────────────────
$token  = trim($_GET['token'] ?? '');
$error  = null;
$success = null;
$comment = null;
$alreadyAppealed = false;

if (empty($token)) {
    $error = 'Link non valido o scaduto.';
} else {
    $decoded = verifyToken($token);

    if (!$decoded) {
        $error = 'Il link di ricorso non è valido oppure è scaduto (validità 30 giorni).';
    } else {
        $comment = DB::table('comments')
            ->where('id', $decoded['comment_id'])
            ->where('appeal_token', $token)
            ->first();

        if (!$comment) {
            $error = 'Commento non trovato o link già utilizzato.';
        } elseif (!in_array($comment->status, ['hidden', 'hidden_reportable'], true)) {
            // Comment was already restored or removed — appeal no longer needed
            if ($comment->status === 'approved') {
                $success = 'Il tuo commento è già stato ripristinato. Grazie per la pazienza.';
            } else {
                $error = 'Non è possibile presentare ricorso per questo commento nel suo stato attuale.';
            }
        } else {
            // Check if appeal was already submitted
            $existing = DB::table('appeal_records')
                ->where('comment_id', $decoded['comment_id'])
                ->where('social_user_id', $decoded['social_user_id'])
                ->first();

            if ($existing) {
                $alreadyAppealed = true;
                $appealStatus    = $existing->status;
            }
        }
    }
}

// ── Handle POST (appeal submission) ───────────────────────────────────────
if ($_SERVER['REQUEST_METHOD'] === 'POST' && $comment && !$alreadyAppealed && !$error) {
    $appealText = trim($_POST['appeal_text'] ?? '');

    if (strlen($appealText) < 10) {
        $error = 'Inserisci una motivazione di almeno 10 caratteri.';
    } elseif (strlen($appealText) > 2000) {
        $error = 'La motivazione non può superare i 2000 caratteri.';
    } else {
        $decoded = verifyToken($token);
        DB::table('appeal_records')->insert([
            'comment_id'     => $decoded['comment_id'],
            'social_user_id' => $decoded['social_user_id'],
            'appeal_text'    => $appealText,
            'status'         => 'pending',
            'submitted_at'   => date('Y-m-d H:i:s'),
        ]);

        // Flag comment with dedicated appeal status — kept OUT of the normal
        // human review queue, managed exclusively from the Appeals tab.
        DB::table('comments')
            ->where('id', $decoded['comment_id'])
            ->update(['status' => 'appeal_pending']);

        $success = 'Il tuo ricorso è stato inviato. I nostri moderatori lo esamineranno al più presto.';
        $alreadyAppealed = true;
    }
}

// ── Render ─────────────────────────────────────────────────────────────────
$siteName = $_ENV['SITE_NAME'] ?? 'Moderation Hub';
?>
