<body>
<div class="card">
  <div class="logo"><?= h($siteName) ?></div>

  <?php if ($error): ?>
    <h1>Link non valido</h1>
    <div class="alert alert-error"><?= h($error) ?></div>
    <p class="subtitle">Se hai ricevuto questo link via Facebook e ritieni ci sia un errore, contatta la redazione direttamente sulla pagina.</p>

  <?php elseif ($success): ?>
    <h1>✓ Ricorso inviato</h1>
    <div class="alert alert-success"><?= h($success) ?></div>
    <p class="subtitle">Riceverai una notifica sulla tua pagina Facebook una volta che il moderatore avrà esaminato il tuo ricorso.</p>

  <?php elseif ($alreadyAppealed): ?>
    <h1>Ricorso già inviato</h1>
    <?php if (($appealStatus ?? '') === 'pending'): ?>
      <div class="alert alert-info">Il tuo ricorso è in attesa di revisione da parte di un moderatore. Ti risponderemo il prima possibile.</div>
    <?php elseif (($appealStatus ?? '') === 'rejected'): ?>
      <div class="alert alert-error">Il tuo ricorso è stato esaminato e la decisione di nascondere il commento è stata confermata.</div>
    <?php endif; ?>

  <?php elseif ($comment): ?>
    <h1>Richiedi revisione del commento</h1>
    <p class="subtitle">Il tuo commento è stato temporaneamente nascosto dalla nostra redazione. Se ritieni che la decisione sia errata, puoi presentare un ricorso qui sotto.</p>

    <?php if ($comment->status === 'hidden_reportable'): ?>
      <div class="badge">⚠️ Contenuto segnalato per valutazione legale</div>
    <?php endif; ?>

    <div class="comment-label">Il tuo commento</div>
    <div class="comment-box"><?= h($comment->content) ?></div>

    <form method="POST" action="">
      <input type="hidden" name="token" value="<?= h($token) ?>">
      <label for="appeal_text">Perché ritieni che il commento non violi le nostre linee guida?</label>
      <textarea
        id="appeal_text"
        name="appeal_text"
        maxlength="2000"
        placeholder="Spiega brevemente il contesto o le tue ragioni…"
        oninput="document.getElementById('cc').textContent = this.value.length + '/2000'"
        required
      ></textarea>
      <div class="char-count"><span id="cc">0</span>/2000</div>
      <button type="submit">Invia ricorso</button>
    </form>

  <?php endif; ?>

  <div class="footer">
    Questo sistema di moderazione è gestito dalla redazione di <?= h($siteName) ?>.<br>
    Le decisioni di moderazione seguono le nostre <a href="/privacy" style="color:#6366f1">linee guida della community</a>.
  </div>
</div>
